public static boolean isIncreasing(int n) {
    while (n >= 10) {
        int last = n % 10;
        int before = n / 10 % 10;
        if (before >= last) {
            return false;
        }
        n = n / 10;
    }
    return true;
}

public static int mostFrequentDigit(int n) {
    int best = 0;
    int bestCount = 0;
    for (int d = 0; d <= 9; d++) {
        int count = 0;
        int m = n;
        while (m > 0) {
            if (m % 10 == d) {
                count++;
            }
            m = m / 10;
        }
        if (count > bestCount) {
            bestCount = count;
            best = d;
        }
    }
    return best;
}

